import { describe, expect, it } from "vitest";

import { highlightLine, highlightSql } from "./highlight";
import {
  buildRlsSql,
  getPreset,
  isValidIdentifier,
  RLS_DEFAULTS,
  RLS_OPERATIONS,
  RLS_PRESETS,
  type RlsInput,
} from "./logic";

const OWNER_SQL = `-- Row-level security for "public"."posts" — preset: owner only.
-- Generated by the free RLS policy generator: https://github.com/Supastack-dev/supastack-tools
-- Postgres ORs policies together: drop any existing policies on this table before re-applying.
-- Assumes "public"."posts"."user_id" references auth.users(id).

alter table "public"."posts" enable row level security;

-- Select: signed-in users can only read rows they own.
create policy "posts_select_owner"
on "public"."posts"
for select to authenticated
using (auth.uid() = "posts"."user_id");

-- Insert: new rows must set "posts"."user_id" to the caller.
create policy "posts_insert_owner"
on "public"."posts"
for insert to authenticated
with check (auth.uid() = "posts"."user_id");

-- Update: only the owner can change a row — ownership can't be moved.
create policy "posts_update_owner"
on "public"."posts"
for update to authenticated
using (auth.uid() = "posts"."user_id")
with check (auth.uid() = "posts"."user_id");

-- Delete: only the owner can remove a row.
create policy "posts_delete_owner"
on "public"."posts"
for delete to authenticated
using (auth.uid() = "posts"."user_id");`;

function input(overrides: Partial<RlsInput> = {}): RlsInput {
  return { table: "posts", preset: "owner", ...overrides };
}

describe("isValidIdentifier", () => {
  it.each(["a", "_x", "posts", "workspace_membership", "col_123"])("accepts %s", (value) => {
    expect(isValidIdentifier(value)).toBe(true);
  });

  it.each(["", "Posts", "9lives", "my table", "my-table", "a.b", 'we"ird', "user;drop"])(
    "rejects %s",
    (value) => {
      expect(isValidIdentifier(value)).toBe(false);
    },
  );

  it("rejects identifiers longer than 63 bytes (Postgres truncates past that)", () => {
    expect(isValidIdentifier("a".repeat(63))).toBe(true);
    expect(isValidIdentifier("a".repeat(64))).toBe(false);
  });
});

describe("presets", () => {
  it("exposes the seven documented presets", () => {
    expect(RLS_PRESETS.map((preset) => preset.id)).toEqual([
      "owner",
      "team",
      "team-write",
      "public-read",
      "authenticated-read",
      "public-insert",
      "locked-down",
    ]);
    for (const preset of RLS_PRESETS) {
      expect(getPreset(preset.id)).toBe(preset);
      expect(preset.token).toMatch(/^[a-z]+$/);
      // Every preset must declare which ops it can emit, with its defaults
      // inside that set.
      for (const op of preset.defaultOperations) {
        expect(preset.allowedOperations).toContain(op);
      }
    }
  });

  it("defaults to all four operations except insert-only and locked-down presets", () => {
    for (const preset of RLS_PRESETS) {
      const expected =
        preset.id === "locked-down" ? [] : preset.id === "public-insert" ? ["insert"] : RLS_OPERATIONS;
      expect(preset.defaultOperations).toEqual(expected);
    }
  });
});

describe("buildRlsSql — owner preset", () => {
  it("emits the full owner-only policy set verbatim", () => {
    const result = buildRlsSql(input());
    expect(result).toEqual({ ok: true, sql: OWNER_SQL, statements: expect.any(Array) });
    if (!result.ok) return;
    expect(result.statements).toHaveLength(5);
    expect(result.statements[0]).toContain("enable row level security");
  });

  it("honours a custom schema and owner column, quoting every identifier", () => {
    const result = buildRlsSql(
      input({ schema: "app", ownerColumn: "author_id", table: "comments" }),
    );
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.sql).toContain('alter table "app"."comments" enable row level security;');
    expect(result.sql).toContain('create policy "comments_select_owner"');
    expect(result.sql).toContain('on "app"."comments"');
    expect(result.sql).toContain('using (auth.uid() = "comments"."author_id")');
  });
});

describe("buildRlsSql — team preset", () => {
  const team = input({
    preset: "team",
    membershipTable: "workspace_membership",
    workspaceColumn: "workspace_id",
    memberColumn: "user_id",
  });

  it("reads through an exists() subquery on the membership table", () => {
    const result = buildRlsSql(team);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.sql).toContain('create policy "posts_select_team"');
    expect(result.sql).toContain(
      [
        "exists (",
        "  select 1",
        '  from "public"."workspace_membership" as "m"',
        '  where "m"."workspace_id" = "posts"."workspace_id"',
        '    and "m"."user_id" = auth.uid()',
        ")",
      ].join("\n"),
    );
  });

  it("keeps writes owner-checked", () => {
    const result = buildRlsSql(team);
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain('with check (auth.uid() = "posts"."user_id")');
    expect(result.sql).toContain('create policy "posts_delete_team"');
    expect(result.sql).toContain(
      'for delete to authenticated\nusing (auth.uid() = "posts"."user_id")',
    );
  });

  it("warns about recursion through the membership table", () => {
    const result = buildRlsSql(team);
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain("non-recursive");
  });

  it.each(["membershipTable", "workspaceColumn", "memberColumn"] as const)(
    "requires %s",
    (field) => {
      const result = buildRlsSql({ ...team, [field]: "" });
      expect(result.ok).toBe(false);
      if (result.ok) return;
      expect(result.errors.map((error) => error.field)).toContain(field);
    },
  );
});

describe("buildRlsSql — read presets", () => {
  it("public-read opens select to anon + authenticated, writes stay owner-only", () => {
    const result = buildRlsSql(input({ preset: "public-read" }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain('create policy "posts_select_public"');
    expect(result.sql).toContain("for select to anon, authenticated\nusing (true)");
    expect(result.sql).toContain(
      'for insert to authenticated\nwith check (auth.uid() = "posts"."user_id")',
    );
  });

  it("authenticated-read scopes select to the authenticated role", () => {
    const result = buildRlsSql(input({ preset: "authenticated-read" }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain('create policy "posts_select_authenticated"');
    expect(result.sql).toContain("for select to authenticated\nusing (true)");
    expect(result.sql).not.toContain("to anon");
  });
});

describe("buildRlsSql — locked-down preset", () => {
  it("enables RLS with no policies and documents the service-role bypass", () => {
    const result = buildRlsSql(input({ preset: "locked-down" }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.statements).toEqual(['alter table "public"."posts" enable row level security;']);
    expect(result.sql).not.toContain("create policy");
    expect(result.sql).toContain("service_role");
  });

  it("ignores the operation list entirely", () => {
    const result = buildRlsSql(input({ preset: "locked-down", operations: ["select", "delete"] }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.statements).toHaveLength(1);
  });
});

describe("buildRlsSql — operation toggles", () => {
  it("omits deselected operations and notes the denial in the SQL", () => {
    const result = buildRlsSql(input({ operations: ["select", "insert"] }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).not.toContain("for update to");
    expect(result.sql).not.toContain("for delete to");
    expect(result.sql).toContain("No update or delete policy");
  });

  it("keeps canonical select/insert/update/delete order regardless of input order", () => {
    const result = buildRlsSql(input({ operations: ["delete", "select"] }));
    if (!result.ok) throw new Error("expected ok");
    const selectAt = result.sql.indexOf("for select to");
    const deleteAt = result.sql.indexOf("for delete to");
    expect(selectAt).toBeGreaterThan(-1);
    expect(deleteAt).toBeGreaterThan(selectAt);
  });

  it("still enables RLS when every operation is deselected", () => {
    const result = buildRlsSql(input({ operations: [] }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.statements).toEqual(['alter table "public"."posts" enable row level security;']);
    expect(result.sql).toContain("denied");
  });
});

describe("buildRlsSql — validation", () => {
  it("reports one error per invalid required field", () => {
    const result = buildRlsSql(input({ table: "My Posts", schema: "1bad" }));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.errors.map((error) => error.field).sort()).toEqual(["schema", "table"]);
    for (const error of result.errors) {
      expect(error.message).toBeTruthy();
    }
  });

  it("flags empty required fields as required rather than malformed", () => {
    const result = buildRlsSql(input({ table: "" }));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.errors[0]?.field).toBe("table");
    expect(result.errors[0]?.message).toMatch(/required/i);
  });

  it("does not require the owner column for the locked-down preset", () => {
    const result = buildRlsSql(input({ preset: "locked-down", ownerColumn: "nope!!" }));
    expect(result.ok).toBe(true);
  });

  it("ignores membership fields for non-team presets", () => {
    const result = buildRlsSql(input({ membershipTable: "!!!" }));
    expect(result.ok).toBe(true);
  });

  it("applies documented defaults for schema and owner column", () => {
    const result = buildRlsSql({ table: "posts", preset: "owner" });
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain('"public"."posts"');
    expect(result.sql).toContain('"posts"."user_id"');
    expect(RLS_DEFAULTS.schema).toBe("public");
    expect(RLS_DEFAULTS.ownerColumn).toBe("user_id");
  });
});

describe("buildRlsSql — team-write preset", () => {
  const teamWrite = input({
    preset: "team-write",
    membershipTable: "workspace_membership",
    workspaceColumn: "workspace_id",
    memberColumn: "user_id",
  });

  it("guards reads and writes by membership, not just ownership", () => {
    const result = buildRlsSql(teamWrite);
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain('create policy "posts_select_teamwrite"');
    expect(result.sql).toContain('create policy "posts_delete_teamwrite"');
    // update carries the membership check on both sides.
    expect(result.sql).toContain("for update to authenticated\nusing (exists (");
    // insert requires ownership AND membership.
    expect(result.sql).toContain('with check ((auth.uid() = "posts"."user_id") and\nexists (');
  });
});

describe("buildRlsSql — public-insert preset", () => {
  it("emits exactly one insert policy open to anon and authenticated", () => {
    const result = buildRlsSql(input({ preset: "public-insert" }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain('create policy "posts_insert_publicinsert"');
    expect(result.sql).toContain("for insert to anon, authenticated\nwith check (true)");
    expect(result.statements).toHaveLength(2); // alter + insert policy
    expect(result.sql).toContain("No select, update or delete policy");
  });

  it("refuses to emit other operations even when requested", () => {
    const result = buildRlsSql(
      input({ preset: "public-insert", operations: [...RLS_OPERATIONS] }),
    );
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).not.toContain("for select");
    expect(result.sql).not.toContain("for update");
    expect(result.sql).not.toContain("for delete");
    expect(result.statements).toHaveLength(2);
  });

  it("needs no owner column — there is nothing to read back", () => {
    const result = buildRlsSql(input({ preset: "public-insert", ownerColumn: "" }));
    expect(result.ok).toBe(true);
  });
});

describe("buildRlsSql — force + drop options", () => {
  it("emits force row level security after enable when asked", () => {
    const result = buildRlsSql(input({ force: true }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain(
      'alter table "public"."posts" force row level security;',
    );
    expect(result.sql).toContain("the owner role bypasses");
    // enable precedes force; force precedes the first policy.
    const enableAt = result.sql.indexOf("enable row level security;");
    const forceAt = result.sql.indexOf("force row level security;");
    const policyAt = result.sql.indexOf("create policy");
    expect(forceAt).toBeGreaterThan(enableAt);
    expect(policyAt).toBeGreaterThan(forceAt);
  });

  it("keeps force off by default", () => {
    const result = buildRlsSql(input());
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).not.toContain("force row level security");
  });

  it("emits drop policy if exists before each create when asked", () => {
    const result = buildRlsSql(input({ dropExisting: true }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain(
      'drop policy if exists "posts_select_owner" on "public"."posts";',
    );
    expect(result.sql.match(/drop policy if exists/g)).toHaveLength(4);
    // Each drop lands directly above its create.
    const dropAt = result.sql.indexOf('drop policy if exists "posts_select_owner"');
    const createAt = result.sql.indexOf('create policy "posts_select_owner"');
    expect(createAt).toBeGreaterThan(dropAt);
  });

  it("applies both options together", () => {
    const result = buildRlsSql(input({ force: true, dropExisting: true }));
    if (!result.ok) throw new Error("expected ok");
    expect(result.sql).toContain("force row level security");
    expect(result.sql).toContain("drop policy if exists");
  });
});

describe("highlightSql", () => {
  it("marks whole comment lines and keeps line count", () => {
    const lines = highlightSql("-- hello\nalter table t enable row level security;");
    expect(lines).toHaveLength(2);
    expect(lines[0]).toEqual([{ text: "-- hello", kind: "comment" }]);
  });

  it("classifies keywords, quoted identifiers, roles and literals", () => {
    const kinds = (text: string) => highlightLine(text).map((t) => `${t.kind}:${t.text}`);
    expect(kinds('create policy "p" on "public"."posts" for select to authenticated')).toEqual(
      expect.arrayContaining([
        "keyword:create",
        "keyword:policy",
        'ident:"p"',
        'ident:"public"',
        'ident:"posts"',
        "keyword:for",
        "keyword:select",
        "keyword:to",
        "role:authenticated",
      ]),
    );
    expect(kinds("with check (true)")).toEqual(
      expect.arrayContaining(["keyword:with", "keyword:check", "literal:true"]),
    );
    expect(kinds("using (auth.uid() = t.id)")).toEqual(
      expect.arrayContaining(["keyword:using", "func:auth.uid"]),
    );
  });

  it("keeps comment tails inline after real tokens", () => {
    const tokens = highlightLine('alter table "t" enable row level security; -- go');
    expect(tokens.at(-1)).toEqual({ text: "-- go", kind: "comment" });
    expect(tokens.some((t) => t.kind === "keyword")).toBe(true);
  });
});
